import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  Pill,
  Phone,
  Stethoscope,
  ChevronRight,
  Settings,
  MessageSquare,
  Sparkles,
  Scan,
  MapPin,
} from 'lucide-react';
import { QuickActionCard } from '@/components/ui/QuickActionCard';
import { MedCard } from '@/components/ui/MedCard';
import { DiseaseFinder } from '@/components/disease-finder/DiseaseFinder';
import { SpecialistDirectory } from '@/components/disease-finder/SpecialistDirectory';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';
import type { Tables } from '@/integrations/supabase/types';

type Medication = Tables<'medications'>;

const Home = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [userName, setUserName] = useState('User');
  const [medications, setMedications] = useState<Medication[]>([]);
  const [greeting, setGreeting] = useState('Good morning');
  const [takenMeds, setTakenMeds] = useState<Set<string>>(new Set());
  const [showDirectory, setShowDirectory] = useState(false);
  const [selectedSpecialty, setSelectedSpecialty] = useState('');

  useEffect(() => {
    // Set greeting based on time
    const hour = new Date().getHours();
    if (hour < 12) setGreeting('Good morning');
    else if (hour < 17) setGreeting('Good afternoon');
    else setGreeting('Good evening');

    if (user) {
      loadUserData();
    }
  }, [user]);

  const loadUserData = async () => {
    if (!user) return;

    // Fetch profile name
    const { data: profile } = await supabase
      .from('profiles')
      .select('full_name')
      .eq('user_id', user.id)
      .maybeSingle();

    if (profile?.full_name) {
      setUserName(profile.full_name.split(' ')[0]);
    }

    // Fetch medications
    const { data: meds } = await supabase
      .from('medications')
      .select('*')
      .eq('user_id', user.id);

    if (meds) {
      setMedications(meds);
    }
  };

  const getNextMedication = () => {
    if (medications.length === 0) return null;
    const now = new Date();
    const currentTime = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

    // Find next medication by time
    const sorted = [...medications].sort((a, b) => {
      const aTime = a.times?.[0] || '00:00';
      const bTime = b.times?.[0] || '00:00';
      return aTime.localeCompare(bTime);
    });

    return sorted.find(m => (m.times?.[0] || '00:00') >= currentTime && !takenMeds.has(m.id)) || sorted[0];
  };

  const handleTakeMed = async (medId: string) => {
    if (!user) return;
    setTakenMeds(prev => new Set(prev).add(medId));
    await supabase.from('health_logs').insert({
      user_id: user.id,
      type: 'med_taken',
      data: { medicationId: medId, timestamp: new Date().toISOString() },
    });
  };

  const handleFindSpecialist = (specialty: string) => {
    setSelectedSpecialty(specialty);
    setShowDirectory(true);
  };

  const nextMed = getNextMedication();

  return (
    <div className="min-h-screen bg-background">
      {/* Header with gradient */}
      <header className="sticky top-0 z-40 glass gradient-header border-b border-border/50">
        <div className="container max-w-lg mx-auto px-4 py-4">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="font-display text-xl font-semibold text-foreground">
                {greeting}, <span className="text-gradient">{userName}</span>
              </h1>
              <p className="text-sm text-muted-foreground mt-0.5">
                {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
              </p>
            </div>
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => navigate('/settings')}
              className="p-2.5 bg-card rounded-xl border border-border/50 shadow-card"
            >
              <Settings className="w-5 h-5 text-muted-foreground" />
            </motion.button>
          </div>
        </div>
      </header>

      <main className="container max-w-lg mx-auto px-4 py-6 space-y-6">
        {/* Medications - Top of Dashboard */}
        <section>
          <div className="flex items-center justify-between mb-3">
            <h2 className="font-display font-semibold text-foreground">Medications</h2>
            <button
              onClick={() => navigate('/medications')}
              className="text-sm text-primary font-medium flex items-center gap-1"
            >
              View all <ChevronRight className="w-4 h-4" />
            </button>
          </div>
          {nextMed ? (
            <MedCard
              name={nextMed.name}
              dosage={nextMed.dosage}
              time={nextMed.times?.[0] || '08:00'}
              taken={takenMeds.has(nextMed.id)}
              onTake={() => handleTakeMed(nextMed.id)}
            />
          ) : (
            <div className="bg-card rounded-2xl p-6 shadow-card border border-border/50 text-center">
              <Pill className="w-10 h-10 text-muted-foreground mx-auto mb-3 opacity-50" />
              <p className="text-muted-foreground">No medications scheduled</p>
              <button
                onClick={() => navigate('/medications')}
                className="mt-3 text-sm font-medium text-primary"
              >
                Add medication
              </button>
            </div>
          )}
        </section>

        {/* Disease Finder */}
        <DiseaseFinder onFindSpecialist={handleFindSpecialist} />

        {/* Quick Actions - Core Modules */}
        <section>
          <h2 className="font-display font-semibold text-foreground mb-3">Quick Actions</h2>
          <div className="grid grid-cols-2 gap-3">
            <QuickActionCard
              icon={Scan}
              label="Scan Rx"
              description="Prescription OCR"
              onClick={() => navigate('/scan')}
            />
            <QuickActionCard
              icon={Pill}
              label="Drug Checker"
              description="Check interactions"
              variant="warning"
              onClick={() => navigate('/interactions')}
            />
            <QuickActionCard
              icon={MessageSquare}
              label="AI Chat"
              description="Clinical assistant"
              variant="primary"
              onClick={() => navigate('/chat')}
            />
            <QuickActionCard
              icon={Phone}
              label="Emergency SOS"
              description="Quick access"
              variant="danger"
              onClick={() => navigate('/emergency')}
            />
          </div>
        </section>

        {/* Find Healthcare */}
        <section>
          <QuickActionCard
            icon={MapPin}
            label="Find Hospitals & Doctors"
            description="Browse our directory of specialists and facilities"
            onClick={() => setShowDirectory(true)}
            className="w-full"
          />
        </section>

        {/* Health Tips */}
        <section className="bg-gradient-to-br from-primary/10 via-accent/15 to-info/10 rounded-3xl p-5 border border-accent/20">
          <div className="flex items-start gap-4">
            <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-primary to-accent flex items-center justify-center flex-shrink-0 shadow-glow">
              <Sparkles className="w-6 h-6 text-primary-foreground" />
            </div>
            <div>
              <h3 className="font-display font-semibold text-foreground">Daily Health Tip</h3>
              <p className="text-sm text-muted-foreground mt-1">
                Stay hydrated! Aim for 8 glasses of water daily to support your medications' effectiveness.
              </p>
            </div>
          </div>
        </section>
      </main>

      {/* Specialist Directory Modal */}
      <SpecialistDirectory
        isOpen={showDirectory}
        onClose={() => setShowDirectory(false)}
        initialSpecialty={selectedSpecialty}
      />
    </div>
  );
};

export default Home;

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowLeft, Plus, Pill, Calendar, Clock, Trash2, Loader2 } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { MedCard } from '@/components/ui/MedCard';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import type { Tables } from '@/integrations/supabase/types';

type Medication = Tables<'medications'>;

const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

const Medications = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [medications, setMedications] = useState<Medication[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedDay, setSelectedDay] = useState(new Date().getDay() || 7);
  const [takenMeds, setTakenMeds] = useState<Set<string>>(new Set());
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newMed, setNewMed] = useState({
    name: '',
    dosage: '',
    frequency: 'daily',
    time: '08:00',
  });

  useEffect(() => {
    if (user) {
      loadMedications();
    }
  }, [user]);

  const loadMedications = async () => {
    if (!user) return;

    try {
      const { data, error } = await supabase
        .from('medications')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setMedications(data || []);
    } catch (error) {
      console.error('Error loading medications:', error);
      toast.error('Failed to load medications');
    } finally {
      setLoading(false);
    }
  };

  const handleAddMedication = async () => {
    if (!newMed.name || !newMed.dosage) {
      toast.error('Please fill in all required fields');
      return;
    }
    if (!user) {
      toast.error('Please sign in to add medications');
      return;
    }

    setIsSubmitting(true);
    try {
      const { error } = await supabase.from('medications').insert({
        user_id: user.id,
        name: newMed.name,
        dosage: newMed.dosage,
        frequency: newMed.frequency,
        times: [newMed.time],
        stock_count: 30,
      });

      if (error) throw error;

      await loadMedications();
      setIsAddOpen(false);
      setNewMed({ name: '', dosage: '', frequency: 'daily', time: '08:00' });
      toast.success('Medication added successfully');
    } catch (error) {
      console.error('Error adding medication:', error);
      toast.error('Failed to add medication');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDeleteMedication = async (id: string) => {
    try {
      const { error } = await supabase
        .from('medications')
        .delete()
        .eq('id', id);

      if (error) throw error;

      await loadMedications();
      toast.success('Medication removed');
    } catch (error) {
      console.error('Error deleting medication:', error);
      toast.error('Failed to delete medication');
    }
  };

  const handleTakeMed = async (medId: string) => {
    if (!user) return;

    setTakenMeds(prev => new Set(prev).add(medId));

    try {
      await supabase.from('health_logs').insert({
        user_id: user.id,
        type: 'med_taken',
        data: { medicationId: medId, timestamp: new Date().toISOString() },
      });
      toast.success('Medication marked as taken!');
    } catch (error) {
      console.error('Error logging medication:', error);
    }
  };

  // Sort medications by time
  const sortedMeds = [...medications].sort((a, b) => {
    const aTime = a.times?.[0] || '00:00';
    const bTime = b.times?.[0] || '00:00';
    return aTime.localeCompare(bTime);
  });

  return (
    <div className="min-h-screen bg-background">
      {/* Header */}
      <header className="sticky top-0 z-40 glass border-b border-border/50">
        <div className="container max-w-lg mx-auto px-4 py-4">
          <div className="flex items-center gap-4">
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => navigate(-1)}
              className="p-2 -ml-2 rounded-xl hover:bg-secondary transition-colors"
            >
              <ArrowLeft className="w-5 h-5 text-foreground" />
            </motion.button>
            <div className="flex-1">
              <h1 className="font-display text-xl font-semibold text-foreground">Medications</h1>
              <p className="text-sm text-muted-foreground">Manage your daily medications</p>
            </div>
            <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
              <DialogTrigger asChild>
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  className="p-2.5 bg-primary rounded-xl shadow-sm"
                >
                  <Plus className="w-5 h-5 text-primary-foreground" />
                </motion.button>
              </DialogTrigger>
              <DialogContent className="sm:max-w-md">
                <DialogHeader>
                  <DialogTitle className="font-display">Add Medication</DialogTitle>
                </DialogHeader>
                <div className="space-y-4 mt-4">
                  <div>
                    <Label htmlFor="med-name">Medication Name</Label>
                    <Input
                      id="med-name"
                      placeholder="e.g., Aspirin"
                      value={newMed.name}
                      onChange={e => setNewMed(prev => ({ ...prev, name: e.target.value }))}
                    />
                  </div>
                  <div>
                    <Label htmlFor="med-dosage">Dosage</Label>
                    <Input
                      id="med-dosage"
                      placeholder="e.g., 100mg"
                      value={newMed.dosage}
                      onChange={e => setNewMed(prev => ({ ...prev, dosage: e.target.value }))}
                    />
                  </div>
                  <div>
                    <Label htmlFor="med-time">Time</Label>
                    <Input
                      id="med-time"
                      type="time"
                      value={newMed.time}
                      onChange={e => setNewMed(prev => ({ ...prev, time: e.target.value }))}
                    />
                  </div>
                  <Button onClick={handleAddMedication} className="w-full" disabled={isSubmitting}>
                    {isSubmitting ? (
                      <>
                        <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                        Adding...
                      </>
                    ) : (
                      'Add Medication'
                    )}
                  </Button>
                </div>
              </DialogContent>
            </Dialog>
          </div>
        </div>
      </header>

      {loading ? (
        <div className="flex items-center justify-center min-h-[50vh]">
          <Loader2 className="w-8 h-8 animate-spin text-primary" />
        </div>
      ) : (
        <main className="container max-w-lg mx-auto px-4 py-6 space-y-6">
        {/* Week Calendar Strip */}
        <section className="bg-card rounded-2xl p-4 shadow-card border border-border/50">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-display font-medium text-foreground flex items-center gap-2">
              <Calendar className="w-4 h-4 text-primary" />
              This Week
            </h2>
          </div>
          <div className="flex gap-2">
            {DAYS.map((day, index) => {
              const dayNum = index + 1;
              const isSelected = selectedDay === dayNum;
              const isToday = new Date().getDay() === dayNum || (new Date().getDay() === 0 && dayNum === 7);

              return (
                <motion.button
                  key={day}
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => setSelectedDay(dayNum)}
                  className={`flex-1 py-3 rounded-xl text-center transition-all ${
                    isSelected
                      ? 'bg-primary text-primary-foreground shadow-sm'
                      : isToday
                      ? 'bg-primary/10 text-primary'
                      : 'bg-secondary text-muted-foreground hover:bg-secondary/80'
                  }`}
                >
                  <span className="text-xs font-medium block">{day}</span>
                </motion.button>
              );
            })}
          </div>
        </section>

        {/* Medications List */}
        <section>
          <h2 className="font-display font-semibold text-foreground mb-3 flex items-center gap-2">
            <Clock className="w-4 h-4 text-primary" />
            Today's Schedule
          </h2>
          <div className="space-y-3">
            <AnimatePresence mode="popLayout">
              {sortedMeds.length > 0 ? (
                sortedMeds.map(med => (
                  <motion.div
                    key={med.id}
                    layout
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.95 }}
                    className="relative group"
                  >
                    <MedCard
                      name={med.name}
                      dosage={med.dosage}
                      time={med.times?.[0] || '08:00'}
                      taken={takenMeds.has(med.id)}
                      onTake={() => handleTakeMed(med.id)}
                    />
                    <motion.button
                      initial={{ opacity: 0 }}
                      whileHover={{ scale: 1.1 }}
                      className="absolute top-4 right-4 p-2 bg-destructive/10 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity"
                      onClick={() => handleDeleteMedication(med.id)}
                    >
                      <Trash2 className="w-4 h-4 text-destructive" />
                    </motion.button>
                  </motion.div>
                ))
              ) : (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="bg-card rounded-2xl p-8 shadow-card border border-border/50 text-center"
                >
                  <Pill className="w-12 h-12 text-muted-foreground mx-auto mb-4 opacity-50" />
                  <h3 className="font-display font-medium text-foreground mb-2">No medications</h3>
                  <p className="text-sm text-muted-foreground mb-4">
                    Start by adding your first medication
                  </p>
                  <Button onClick={() => setIsAddOpen(true)}>
                    <Plus className="w-4 h-4 mr-2" />
                    Add Medication
                  </Button>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </section>
        </main>
      )}
    </div>
  );
};

export default Medications;

