import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const GEMINI_API_URL = 'https://generativelanguage.googleapis.com/v1beta/models';

interface ChatRequest {
  messages: { role: string; content: string }[];
  action?: 'chat' | 'symptoms' | 'interactions' | 'scan';
  symptoms?: string[];
  drug1?: string;
  drug2?: string;
  imageBase64?: string;
  imageMimeType?: string;
  userContext?: { age?: number; conditions?: string[] };
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const { messages, action = 'chat', symptoms, drug1, drug2, imageBase64, imageMimeType, userContext } = await req.json() as ChatRequest;
    const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY");

    if (!GEMINI_API_KEY) {
      console.error("GEMINI_API_KEY is not configured");
      throw new Error("GEMINI_API_KEY is not configured");
    }

    let systemContext = "You are MedGuide AI, a helpful healthcare assistant. Always reason step-by-step and provide clear, helpful medical information. Always include a disclaimer that you are not a replacement for professional medical advice.";

    if (userContext) {
      systemContext = `You are MedGuide AI, a helpful healthcare assistant. The user is ${userContext.age || 'unknown'} years old with the following conditions: ${userContext.conditions?.join(', ') || 'none specified'}. Always reason step-by-step and provide clear, helpful medical information. Always include a disclaimer that you are not a replacement for professional medical advice.`;
    }

    let contents: any[] = [
      { role: 'user', parts: [{ text: systemContext }] },
      { role: 'model', parts: [{ text: 'I understand. I am MedGuide AI, ready to help with healthcare questions while always being clear about my limitations as an AI assistant.' }] },
    ];

    // Handle different actions
    if (action === 'symptoms' && symptoms) {
      contents.push({
        role: 'user',
        parts: [{
          text: `Analyze these symptoms and provide a JSON response: ${symptoms.join(', ')}

Return ONLY valid JSON in this exact format:
{
  "conditions": [
    {
      "name": "Condition Name",
      "confidence": 85,
      "description": "Brief description",
      "specialist": "Type of specialist to consult"
    }
  ],
  "recommendations": ["Recommendation 1", "Recommendation 2"],
  "urgencyLevel": "low"
}

Provide top 2-3 most likely conditions with confidence percentages. Urgency levels: low, moderate, high, emergency.`
        }]
      });
    } else if (action === 'interactions' && drug1 && drug2) {
      contents.push({
        role: 'user',
        parts: [{
          text: `Check for drug interactions between "${drug1}" and "${drug2}".

Return ONLY valid JSON in this exact format:
{
  "drug1": "${drug1}",
  "drug2": "${drug2}",
  "riskLevel": "low",
  "description": "Description of the interaction or lack thereof",
  "recommendations": ["Recommendation 1", "Recommendation 2"]
}

Risk levels: low (no significant interaction), moderate (use with caution), high (avoid combination)`
        }]
      });
    } else if (action === 'scan' && imageBase64) {
      contents.push({
        role: 'user',
        parts: [
          {
            text: `Analyze this prescription image and extract medication information.

            Return ONLY valid JSON in this exact format:
            {
              "medications": [
                {
                  "name": "Medication Name",
                  "dosage": "Dosage amount",
                  "frequency": "How often to take",
                  "instructions": "Additional instructions if any"
                }
              ]
            }`
          },
          { inlineData: { mimeType: imageMimeType || 'image/jpeg', data: imageBase64 } }
        ]
      });
    } else if (messages && messages.length > 0) {
      // Regular chat - add message history
      for (const msg of messages) {
        contents.push({
          role: msg.role === 'assistant' || msg.role === 'model' ? 'model' : 'user',
          parts: [{ text: msg.content }]
        });
      }
    }

    console.log("Calling Gemini API with action:", action);

    // Use streaming for chat, non-streaming for structured responses
    if (action === 'chat') {
      const response = await fetch(`${GEMINI_API_URL}/gemini-1.5-flash:streamGenerateContent?key=${GEMINI_API_KEY}&alt=sse`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents,
          generationConfig: {
            temperature: 0.7,
            maxOutputTokens: 2048,
          }
        })
      });

      if (!response.ok) {
        const errorText = await response.text();
        console.error("Gemini API error:", response.status, errorText);

        // Parse error for better user messaging
        let errorMessage = "AI service temporarily unavailable";
        if (response.status === 429) {
          errorMessage = "Rate limit exceeded. Please wait a moment and try again.";
        } else if (response.status === 403) {
          errorMessage = "API key issue. Please check your Gemini API key.";
        }

        return new Response(JSON.stringify({ error: errorMessage }), {
          status: response.status,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      return new Response(response.body, {
        headers: { ...corsHeaders, "Content-Type": "text/event-stream" },
      });
    } else {
      // Non-streaming for structured responses
      const response = await fetch(`${GEMINI_API_URL}/gemini-1.5-flash:generateContent?key=${GEMINI_API_KEY}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents,
          generationConfig: {
            temperature: 0.1,
            maxOutputTokens: 2048,
            response_mime_type: "application/json"
          }
        })
      });

      if (!response.ok) {
        const errorText = await response.text();
        console.error("Gemini API error:", response.status, errorText);

        let errorMessage = "AI service temporarily unavailable";
        if (response.status === 429) {
          errorMessage = "Rate limit exceeded. Please wait a moment and try again.";
        }

        return new Response(JSON.stringify({ error: errorMessage }), {
          status: response.status,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      const data = await response.json();
      const text = data.candidates?.[0]?.content?.parts?.[0]?.text || '';

      return new Response(JSON.stringify({ text }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
  } catch (e) {
    console.error("chat error:", e);
    return new Response(JSON.stringify({ error: e instanceof Error ? e.message : "Unknown error" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

